bool Tracer::armInitial2x(uint32_t targetInitialCalls,std::string& error){std::lock_guard l(mutex_);if(!RuntimeLayoutSupportsInitialNx(status_.target.runtime,error))return false;if(status_.phase!=Phase::Attached||detachRequested_||status_.target.mode!=TraceMode::Initial2x||!status_.target.verified||!status_.initialBreakpointsReady){error="Attach in AOE Initial Nx mode and wait for complete validation breakpoint coverage before arming.";return false;}if(status_.target.runtime.liveValidationRequired&&!CanArmInitialNxFromValidation(liveValidation_,status_.target,status_.profileIdentity)){error="LIVE VALIDATION incomplete: "+(liveValidation_.blockingReason.empty()?std::string("required same-session evidence is missing"):liveValidation_.blockingReason);return false;}if(!ValidInitialCallCount(targetInitialCalls)){error="Initial calls must be a whole number from 1 to 2147483647.";return false;}if(status_.initial2x.armed){error="Reset the completed or aborted Initial Nx experiment before a new ARM.";return false;}if(liveValidation_.skillFamily==AoeSkillFamily::Unknown){error="Use one normal Priest, Mage or Archer AOE cast to identify and validate the skill before ARM.";return false;}status_.initial2x=CreateInitial2xExperiment(status_.target,status_.initial2x.producerObservationAvailable,targetInitialCalls,liveValidation_.skillFamily,liveValidation_.validationInitialCall.prepRva,liveValidation_.validationInitialCall.returnRva);if(!status_.initial2x.armed){error="Validated initial preparation route is unavailable.";return false;}status_.message="AOE INITIAL Nx — ARMED FOR NEXT CAST";Log("initial_n_armed","pid="+std::to_string(status_.target.pid)+" base="+Hex(status_.target.base)+" target="+std::to_string(targetInitialCalls)+" liveValidation="+std::to_string(liveValidation_.replayCriticalValidationPassed));error.clear();return true;}
bool Tracer::prepareInitialExperiment(std::string& error){std::lock_guard l(mutex_);if(status_.phase!=Phase::Attached||detachRequested_||status_.target.mode!=TraceMode::Initial2x||!status_.target.verified||!status_.initialBreakpointsReady){error="Attach in AOE Initial Nx mode and wait for complete validation breakpoint coverage before preparing a new experiment.";return false;}if(status_.initial2x.completed||status_.initial2x.aborted){error="A terminal experiment requires breakpoint reset before a new experiment can be prepared.";return false;}if(status_.initial2x.armed&&(status_.initial2x.initialCallsObserved||status_.initial2x.repeatPending||status_.initial2x.replayInProgress||status_.initial2x.awaitingReplayedCall||status_.initial2x.redirectClaimed)){error="The current Initial Nx cast is active; its configured target is frozen until completion.";return false;}const bool producerAvailable=status_.initial2x.producerObservationAvailable;status_.initial2x={};status_.initial2x.producerObservationAvailable=producerAvailable;status_.message="INITIAL Nx READY — waiting for ARM";error.clear();return true;}
bool Tracer::resetInitialExperiment(std::string& error){std::lock_guard l(mutex_);if(status_.phase!=Phase::Attached||status_.target.mode!=TraceMode::Initial2x){error="Attach in AOE Initial Nx mode before reset.";return false;}if(!status_.initial2x.armed||(!status_.initial2x.completed&&!status_.initial2x.aborted)){error="RESET EXPERIMENT is available after COMPLETED or ABORTED.";return false;}if(initialRequest_.load()!=0){error="Initial Nx breakpoint reset is already pending.";return false;}status_.initial2x={};status_.initialBreakpointsReady=false;initialRequest_=1;status_.message="Resetting Initial Nx state and restoring hardware breakpoint coverage...";error.clear();return true;}
bool Tracer::requestVisualCapture(std::string& error){std::lock_guard l(mutex_);if(status_.phase!=Phase::Attached||detachRequested_){error="Visual capture requires an attached TClient session.";return false;}if(status_.target.mode!=TraceMode::Initial2x){error="Visual capture is unavailable while a research inspector is active.";return false;}if(!status_.target.verified){error="Visual capture requires a validated target profile.";return false;}if(status_.targetInspectorPrepared||status_.targetInspectorTransitionPending||status_.targetWriterTransitionPending){error="Visual capture is unavailable during a research breakpoint transition.";return false;}if(!RuntimeLayoutSupportsVisualSuppression(status_.target.runtime,error))return false;if(InitialNxReplayActive(status_.initial2x)){error="Wait for the active Initial Nx replay to finish before resolving TSkill.";return false;}if(status_.visual.resolved){error.clear();return true;}if(status_.visual.captureBreakpointActive||visualRequest_.load()!=0){error="Visual TSkill capture is already pending.";return false;}status_.visual.phase=VisualRuntimePhase::WaitingForAoeCast;status_.visual.error.clear();visualRequest_=1;status_.message=status_.initialBreakpointsReady?"Visual locator ready; installing one-shot TSkill reader coverage...":"Visual locator ready; rebuilding fresh prep/call/return plus reader coverage...";error.clear();return true;}
